   }
   if(command==='transactional_upload_chunk'){assert.equal(args.offset,staged);staged+=args.data.length;return staged}
   if(command==='transactional_upload_finish'){assert.equal(staged,bytes.length);return {path:'calibration.gcode',sha256:digest,remoteVerified:true}}
   if(command==='local_library_read_begin')return {readId:'read-test',size:bytes.length};
   if(command==='local_library_read_chunk')return {data:[...bytes],nextOffset:bytes.length,done:true,sha256:digest};
   if(command==='local_library_read_abort'||command==='transactional_upload_abort')return true;
   throw new Error('Unexpected command '+command);
  };
