fn verify_remote_sha256(
    printer_key: &str,
    host: &str,
    default_port: u16,
    key: Option<&str>,
    filename: &str,
    expected_size: u64,
    expected_sha256: &str,
    scheduler: &super::scheduler::FarmScheduler,
    cancelled: &AtomicBool,
) -> Result<(), String> {
    let metadata = remote_file_metadata(host, default_port, key, filename)?
        .ok_or("Удалённый файл не найден после публикации")?;
    let size = metadata.0;
    if size != expected_size {
        return Err(format!(
            "Размер удалённого файла не совпадает: {size} вместо {expected_size}"
        ));
    }
    // Verify actual downloaded bytes, including after the vendor checksum
    // fallback. A metadata checksum may repeat the same faulty calculation.
    let actual_sha256 = remote_file_sha256(
        printer_key,
        host,
        default_port,
        key,
        filename,
        expected_size,
        scheduler,
        cancelled,
    )?;
    if !bool::from(
        actual_sha256
            .to_ascii_lowercase()
            .as_bytes()
            .ct_eq(expected_sha256.as_bytes()),
    ) {
        return Err(format!(
            "SHA-256 удалённого файла не совпадает с локальным staging-файлом: expected {expected_sha256}, downloaded {actual_sha256}. Печать не запущена"
        ));
    }
    Ok(())
}

