    host: &str,
    default_port: u16,
    key: Option<&str>,
    filename: &str,
) -> Result<Option<u64>, String> {
    Ok(remote_file_metadata(host, default_port, key, filename)?.map(|value| value.0))
}

fn remote_file_metadata(
    host: &str,
    default_port: u16,
    key: Option<&str>,
    filename: &str,
) -> Result<Option<(u64, Option<String>)>, String> {
    let target = parse_target(host, default_port)?;
    let mut serializer = url::form_urlencoded::Serializer::new(String::new());
    serializer.append_pair("filename", filename);
    let response = http_request(
        &target,
        "GET",
        &format!("/server/files/metadata?{}", serializer.finish()),
        key,
        None,
        &[],
        MAX_JSON_RESPONSE,
        Duration::from_secs(8),
    )?;
    if response.status == 404 {
        return Ok(None);
    }
    if !(200..300).contains(&response.status) {
        return Err(format!("Remote metadata HTTP {}", response.status));
    }
    let json: Value = serde_json::from_slice(&response.body).map_err(|error| error.to_string())?;
    let size = json
        .pointer("/result/size")
        .or_else(|| json.get("size"))
        .and_then(Value::as_u64)
        .ok_or("Moonraker metadata не содержит размер")?;
    let checksum = [
        "/result/sha256",
        "/result/checksum",
        "/result/item/sha256",
        "/result/item/checksum",
        "/sha256",
        "/checksum",
    ]
    .into_iter()
    .find_map(|path| json.pointer(path).and_then(Value::as_str))
    .map(str::trim)
    .filter(|value| value.len() == 64 && value.bytes().all(|byte| byte.is_ascii_hexdigit()))
    .map(str::to_ascii_lowercase);
    Ok(Some((size, checksum)))
}

#[allow(clippy::too_many_arguments)]
fn remote_file_sha256(
    printer_key: &str,
    host: &str,
    default_port: u16,
    key: Option<&str>,
    filename: &str,
    expected_size: u64,
    scheduler: &super::scheduler::FarmScheduler,
    cancelled: &AtomicBool,
) -> Result<String, String> {
    let target = parse_target(host, default_port)?;
    let encoded = filename
        .split('/')
        .map(|segment| url::form_urlencoded::byte_serialize(segment.as_bytes()).collect::<String>())
        .collect::<Vec<_>>()
        .join("/");
    let mut stream = TcpStream::connect_timeout(&target.socket, Duration::from_secs(5))
        .map_err(|error| format!("Remote verification connect failed: {error}"))?;
    stream
        .set_read_timeout(Some(Duration::from_secs(120)))
        .map_err(|error| error.to_string())?;
    stream
        .set_write_timeout(Some(Duration::from_secs(10)))
        .map_err(|error| error.to_string())?;
    let mut request = format!(
        "GET /server/files/gcodes/{encoded} HTTP/1.1\r\nHost: {}\r\nConnection: close\r\nAccept: application/octet-stream\r\n",
        target.authority
    );
    if let Some(key) = key.filter(|value| !value.is_empty()) {
        crate::validate_header_value(key, 512)?;
        request.push_str(&format!("X-Api-Key: {key}\r\n"));
    }
    request.push_str("\r\n");
    stream
        .write_all(request.as_bytes())
        .map_err(|error| format!("Remote verification request failed: {error}"))?;
    let mut reader = BufReader::new(stream);
    let mut status = String::new();
    read_bounded_line(&mut reader, &mut status)?;
    let status_code = status
        .split_whitespace()
        .nth(1)
        .and_then(|value| value.parse::<u16>().ok())
        .ok_or("Remote verification returned an invalid HTTP status")?;
    if !(200..300).contains(&status_code) {
        return Err(format!("Remote verification HTTP {status_code}"));
    }
    let mut content_length = None;
    let mut chunked = false;
    let mut header_bytes = status.len();
    loop {
        let mut line = String::new();
        read_bounded_line(&mut reader, &mut line)?;
        header_bytes = header_bytes.saturating_add(line.len());
        if header_bytes > 64 * 1024 {
            return Err("Remote verification headers exceed the limit".into());
        }
        if line == "\r\n" || line == "\n" {
            break;
        }
        if let Some((name, value)) = line.split_once(':') {
            if name.trim().eq_ignore_ascii_case("content-length") {
                content_length = value.trim().parse::<u64>().ok();
            }
            if name.trim().eq_ignore_ascii_case("transfer-encoding")
                && value.to_ascii_lowercase().contains("chunked")
            {
                chunked = true;
            }
        }
    }
    if content_length.is_some_and(|value| value != expected_size) {
        return Err("Контрольное скачивание вернуло неверный размер файла".into());
    }
    let mut hasher = Sha256::new();
    let mut received = 0_u64;
    if chunked {
        loop {
            let mut size_line = String::new();
            read_bounded_line(&mut reader, &mut size_line)?;
            let size_text = size_line.trim().split(';').next().unwrap_or_default();
            let chunk_size = u64::from_str_radix(size_text, 16)
                .map_err(|_| "Некорректный chunked-ответ контрольного скачивания")?;
            if chunk_size == 0 {
                break;
            }
            hash_exact(
                printer_key,
                &mut reader,
                chunk_size,
                expected_size,
                &mut received,
                &mut hasher,
                scheduler,
                cancelled,
            )?;
            let mut ending = [0_u8; 2];
            reader
                .read_exact(&mut ending)
                .map_err(|error| error.to_string())?;
            if ending != *b"\r\n" {
                return Err("Некорректная граница chunked-ответа".into());
            }
        }
    } else {
        hash_exact(
            printer_key,
            &mut reader,
            content_length.unwrap_or(expected_size),
            expected_size,
            &mut received,
            &mut hasher,
            scheduler,
            cancelled,
        )?;
    }
    if received != expected_size {
        return Err(format!(
            "Контрольное скачивание получило {received} байт вместо {expected_size}"
        ));
    }
    Ok(hex::encode(hasher.finalize()))
}

fn read_bounded_line<R: BufRead>(reader: &mut R, output: &mut String) -> Result<(), String> {
    output.clear();
    reader
        .take(8 * 1024)
        .read_line(output)
        .map_err(|error| error.to_string())?;
    if output.len() >= 8 * 1024 || (!output.ends_with('\n') && !output.is_empty()) {
        return Err("Remote verification returned an oversized HTTP line".into());
    }
    Ok(())
}

#[allow(clippy::too_many_arguments)]
fn hash_exact<R: Read>(
    printer_key: &str,
    reader: &mut R,
    length: u64,
    expected_size: u64,
    received: &mut u64,
    hasher: &mut Sha256,
    scheduler: &super::scheduler::FarmScheduler,
    cancelled: &AtomicBool,
) -> Result<(), String> {
    if (*received).saturating_add(length) > expected_size {
        return Err("Контрольное скачивание превысило ожидаемый размер".into());
    }
    let mut remaining = length;
    let mut buffer = vec![0_u8; MAX_UPLOAD_CHUNK];
    while remaining > 0 {
        if cancelled.load(Ordering::Acquire) {
            return Err("Проверка удалённого файла отменена пользователем".into());
        }
        let maximum = remaining.min(buffer.len() as u64) as usize;
        let read = reader
            .read(&mut buffer[..maximum])
            .map_err(|error| error.to_string())?;
        if read == 0 {
            return Err("Контрольное скачивание завершилось раньше ожидаемого".into());
        }
        scheduler.acquire_bandwidth_for(
            printer_key,
            read,
            OperationPriority::Upload,
            Duration::from_secs(60),
            Some(cancelled),
        )?;
        hasher.update(&buffer[..read]);
        *received = (*received).saturating_add(read as u64);
        remaining -= read as u64;
    }
    Ok(())
}

fn hash_file(path: &Path, expected_size: u64, cancelled: &AtomicBool) -> Result<String, String> {
    let mut file = OpenOptions::new()
        .read(true)
        .open(path)
        .map_err(|error| error.to_string())?;
    let metadata = file.metadata().map_err(|error| error.to_string())?;
    if metadata.len() != expected_size {
        return Err("Размер staging-файла не совпадает с ожидаемым".into());
    }
    let mut hasher = Sha256::new();
    let mut buffer = vec![0_u8; MAX_UPLOAD_CHUNK];
    loop {
        if cancelled.load(Ordering::Acquire) {
            return Err("Загрузка отменена пользователем".into());
        }
        let read = file.read(&mut buffer).map_err(|error| error.to_string())?;
        if read == 0 {
            break;
        }
        hasher.update(&buffer[..read]);
    }
    Ok(hex::encode(hasher.finalize()))
}

fn open_database(path: &Path) -> Result<Connection, String> {
    let connection = Connection::open(path).map_err(|error| error.to_string())?;
    connection
        .execute_batch("PRAGMA journal_mode=WAL; PRAGMA busy_timeout=5000;")
        .map_err(|error| error.to_string())?;
    Ok(connection)
}

fn load_record(connection: &Connection, upload_id: &str) -> Result<Option<UploadRecord>, String> {
    connection
        .query_row(
            "SELECT stable_id,printer_id,owner_id,filename,
                    temporary_name,staging_path,expected_size,received_size,expected_sha256,
                    state,result_path,actual_sha256
             FROM transactional_uploads WHERE upload_id=?1",
            params![upload_id],
            |row| {
                Ok(UploadRecord {
                    stable_id: row.get(0)?,
                    printer_id: row.get(1)?,
                    owner_id: row.get(2)?,
                    filename: row.get(3)?,
                    temporary_name: row.get(4)?,
                    staging_path: PathBuf::from(row.get::<_, String>(5)?),
                    expected_size: row.get::<_, i64>(6)?.max(0) as u64,
                    received_size: row.get::<_, i64>(7)?.max(0) as u64,
                    expected_sha256: row.get(8)?,
                    state: row.get(9)?,
                    result_path: row.get(10)?,
                    actual_sha256: row.get(11)?,
                })
            },
        )
        .optional()
        .map_err(|error| error.to_string())
}

fn validate_staging_path(
    record: &UploadRecord,
    root: &Path,
    upload_id: &str,
) -> Result<(), String> {
    let expected = root.join(format!("{upload_id}.stage"));
    if record.staging_path != expected || record.staging_path.parent() != Some(root) {
        return Err("Путь staging не принадлежит transactional upload".into());
    }
    Ok(())
}

fn validate_staging_file(
    record: &UploadRecord,
    root: &Path,
    upload_id: &str,
) -> Result<(), String> {
    validate_staging_path(record, root, upload_id)?;
    let metadata = fs::symlink_metadata(&record.staging_path)
        .map_err(|error| format!("Staging-файл недоступен: {error}"))?;
    if !metadata.file_type().is_file() {
        return Err("Staging должен быть обычным файлом".into());
    }
    Ok(())
}

fn enforce_staging_quota(connection: &Connection, incoming: u64) -> Result<(), String> {
    let used: i64 = connection
        .query_row(
            "SELECT COALESCE(SUM(expected_size),0) FROM transactional_uploads
             WHERE state IN ('staging','staged','uploading','remote_verified')",
            [],
            |row| row.get(0),
        )
        .map_err(|error| error.to_string())?;
    if (used.max(0) as u64).saturating_add(incoming) > STAGING_QUOTA {
        return Err("Недостаточно квоты staging: общий лимит 512 MiB".into());
    }
    Ok(())
}

fn staging_root(app: &AppHandle) -> Result<PathBuf, String> {
    let root = app
        .path()
        .app_cache_dir()
        .map_err(|error| error.to_string())?
        .join("transactional-uploads-v3");
    fs::create_dir_all(&root).map_err(|error| error.to_string())?;
    set_private_directory_permissions(&root)?;
    Ok(root)
}

fn cleanup_orphans_journal(journal: &Journal, root: &Path, now: i64) -> Result<(), String> {
    let cutoff = now.saturating_sub(ORPHAN_TTL_MS);
    let (expired, active) = journal.read(|connection| {
        let expired = {
            let mut statement = connection
                .prepare(
                    "SELECT upload_id,staging_path FROM transactional_uploads
                     WHERE state NOT IN ('completed','cancelled','abandoned') AND updated_at<?1",
                )
                .map_err(|error| error.to_string())?;
            let rows = statement
                .query_map(params![cutoff], |row| Ok((row.get(0)?, row.get(1)?)))
                .map_err(|error| error.to_string())?
                .collect::<Result<Vec<(String, String)>, _>>()
                .map_err(|error| error.to_string())?;
            rows
        };
        let active = {
            let mut statement = connection
                .prepare(
                    "SELECT upload_id FROM transactional_uploads
                     WHERE state NOT IN ('completed','cancelled','abandoned')",
                )
                .map_err(|error| error.to_string())?;
            let rows = statement
                .query_map([], |row| row.get::<_, String>(0))
                .map_err(|error| error.to_string())?
                .collect::<Result<HashSet<_>, _>>()
                .map_err(|error| error.to_string())?;
            rows
        };
        Ok((expired, active))
    })?;
    let mut expired_ids = Vec::with_capacity(expired.len());
    for (upload_id, path) in expired {
        let candidate = PathBuf::from(path);
        if candidate.parent() == Some(root)
            && candidate.extension().and_then(|value| value.to_str()) == Some("stage")
            && candidate.file_stem().and_then(|value| value.to_str()) == Some(upload_id.as_str())
        {
            let _ = fs::remove_file(candidate);
        }
        expired_ids.push(upload_id);
    }
    if !expired_ids.is_empty() {
        journal.critical(move |connection| {
            let transaction = connection
                .transaction_with_behavior(rusqlite::TransactionBehavior::Immediate)
                .map_err(|error| error.to_string())?;
            for upload_id in expired_ids {
                transaction
                    .execute(
                        "UPDATE transactional_uploads
                         SET state='abandoned',updated_at=?2,last_error='Сиротский staging очищен'
                         WHERE upload_id=?1",
                        params![upload_id, now],
                    )
                    .map_err(|error| error.to_string())?;
            }
            transaction.commit().map_err(|error| error.to_string())
        })?;
    }
    for entry in fs::read_dir(root)
        .map_err(|error| error.to_string())?
        .filter_map(Result::ok)
    {
        let path = entry.path();
        if path.extension().and_then(|value| value.to_str()) != Some("stage") {
            continue;
        }
        let upload_id = path
            .file_stem()
            .and_then(|value| value.to_str())
            .unwrap_or_default();
        let old = entry
            .metadata()
            .ok()
            .and_then(|metadata| metadata.modified().ok())
            .and_then(|modified| SystemTime::now().duration_since(modified).ok())
            .is_some_and(|age| age.as_millis() as i64 > ORPHAN_TTL_MS);
        if !active.contains(upload_id) && old {
            let _ = fs::remove_file(path);
        }
    }
    Ok(())
}

fn cleanup_orphans(database_path: &Path, root: &Path, now: i64) -> Result<(), String> {
    let connection = open_database(database_path)?;
    let cutoff = now.saturating_sub(ORPHAN_TTL_MS);
    let mut statement = connection
        .prepare(
            "SELECT upload_id,staging_path FROM transactional_uploads
             WHERE state NOT IN ('completed','cancelled','abandoned') AND updated_at<?1",
        )
        .map_err(|error| error.to_string())?;
    let expired: Vec<(String, String)> = statement
        .query_map(params![cutoff], |row| Ok((row.get(0)?, row.get(1)?)))
        .map_err(|error| error.to_string())?
        .filter_map(Result::ok)
        .collect();
    drop(statement);
    for (upload_id, path) in expired {
        let candidate = PathBuf::from(path);
        if candidate.parent() == Some(root)
            && candidate.extension().and_then(|value| value.to_str()) == Some("stage")
            && candidate.file_stem().and_then(|value| value.to_str()) == Some(upload_id.as_str())
        {
            let _ = fs::remove_file(candidate);
        }
        connection
            .execute(
                "UPDATE transactional_uploads SET state='abandoned',updated_at=?2,last_error='Сиротский staging очищен' WHERE upload_id=?1",
                params![upload_id, now],
            )
            .map_err(|error| error.to_string())?;
    }
    let entries = fs::read_dir(root).map_err(|error| error.to_string())?;
    for entry in entries.filter_map(Result::ok) {
        let path = entry.path();
        if path.extension().and_then(|value| value.to_str()) != Some("stage") {
            continue;
        }
        let filename = path
            .file_stem()
            .and_then(|value| value.to_str())
            .unwrap_or_default();
        let exists: bool = connection
            .query_row(
                "SELECT EXISTS(SELECT 1 FROM transactional_uploads WHERE upload_id=?1 AND state NOT IN ('completed','cancelled','abandoned'))",
                params![filename],
                |row| row.get(0),
            )
            .unwrap_or(false);
        let old = entry
            .metadata()
            .ok()
            .and_then(|metadata| metadata.modified().ok())
            .and_then(|modified| SystemTime::now().duration_since(modified).ok())
            .is_some_and(|age| age.as_millis() as i64 > ORPHAN_TTL_MS);
        if !exists && old {
            let _ = fs::remove_file(path);
        }
    }
    Ok(())
}

fn deterministic_upload_id(
    stable_id: &str,
    filename: &str,
    file_size: u64,
    expected_sha256: &str,
) -> String {
    let mut hasher = Sha256::new();
    hasher.update(b"klipper-farm-upload-v3\0");
    hasher.update(stable_id.as_bytes());
    hasher.update(b"\0");
    hasher.update(filename.as_bytes());
    hasher.update(b"\0");
    hasher.update(file_size.to_le_bytes());
    hasher.update(expected_sha256.as_bytes());
    hex::encode(hasher.finalize())
}

fn validate_sha256(value: &str) -> Result<(), String> {
    if value.len() != 64 || !value.bytes().all(|byte| byte.is_ascii_hexdigit()) {
        return Err("Ожидается SHA-256 из 64 шестнадцатеричных символов".into());
    }
    Ok(())
}

fn validate_upload_id(value: &str) -> Result<(), String> {
    validate_sha256(value).map_err(|_| "Недопустимый ID transactional upload".into())
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn upload_id_is_stable_and_content_bound() {
        let first = deterministic_upload_id("stable", "part.gcode", 10, &"a".repeat(64));
        let same = deterministic_upload_id("stable", "part.gcode", 10, &"a".repeat(64));
        let changed = deterministic_upload_id("stable", "part.gcode", 11, &"a".repeat(64));
        assert_eq!(first, same);
        assert_ne!(first, changed);
        assert_eq!(first.len(), 64);
    }

    #[test]
    fn sha_validation_is_strict() {
        assert!(validate_sha256(&"f".repeat(64)).is_ok());
        assert!(validate_sha256(&"g".repeat(64)).is_err());
        assert!(validate_sha256("abcd").is_err());
    }
}

