use super::TransactionalCore;
use crate::{engine_client::EngineClient, now_ms, require_role, AuthState, Role, APP_VERSION};
use kf_ipc::EngineCommand;
use rusqlite::{Connection, OptionalExtension};
use serde::Serialize;
