};

const pathMethod=url=>url.startsWith('/server/info')?'server.info':url.startsWith('/printer/info')?'printer.info':url.startsWith('/machine/system_info')?'machine.system_info':url.startsWith('/printer/objects/list')?'printer.objects.list':url.startsWith('/printer/objects/query')?'printer.objects.query':url.startsWith('/server/files/list')?'server.files.list':url.startsWith('/server/webcams/list')?'server.webcams.list':undefined;
const headers={'content-type':'application/json; charset=utf-8','cache-control':'no-store'};
