  const frames=[];let offset=0;
  while(offset+2<=buffer.length){const second=buffer[offset+1],masked=!!(second&0x80);let size=second&0x7f,header=2;if(size===126){if(offset+4>buffer.length)break;size=buffer.readUInt16BE(offset+2);header=4}else if(size===127)break;const maskSize=masked?4:0;if(offset+header+maskSize+size>buffer.length)break;const mask=masked?buffer.subarray(offset+header,offset+header+4):undefined,payload=Buffer.from(buffer.subarray(offset+header+maskSize,offset+header+maskSize+size));if(mask)for(let i=0;i<payload.length;i++)payload[i]^=mask[i%4];frames.push(payload);offset+=header+maskSize+size}
  return{frames,remaining:buffer.subarray(offset)};
};

server.on('upgrade',(request,socket)=>{
